-- WoD Garrison: building interior spawns + work-order NPC flags + resource-cache GO script.
--
-- Building interior NPCs/props were never authored in any TrinityCore-lineage DB (templates exist,
-- spawns did not). These spawns are converted from FirestormWoD's garrison_plot_content (the only
-- community source with the data) into our SpawnMap system: each row is placed on the building's
-- GarrBuilding.SpawnMap at a building-relative position, and Garrison::Plot::CreateGameObject relocates
-- it relative to the building when it is constructed. 554 spawns across 117 buildings, both factions.

-- Garrison resource cache GameObject -> collection script (accrues Garrison Resources over time).
UPDATE `gameobject_template` SET `ScriptName`='go_garrison_cache' WHERE `entry` IN (236916,237191,237720,237722,237723,237724);

-- Work-order NPCs (subname 'Work Orders') flagged as shipment crafters (UNIT_NPC_FLAG_2_SHIPMENT_CRAFTER = 0x10).
UPDATE `creature_template` `ct` JOIN (SELECT DISTINCT `id` FROM `creature` WHERE `guid` >= 12000000) `s` ON `s`.`id`=`ct`.`entry`
  SET `ct`.`npcflag` = `ct`.`npcflag` | (16 << 32)
  WHERE `ct`.`subname`='Work Orders' AND ((`ct`.`npcflag` >> 32) & 16) = 0;

-- Garrison building interior spawns, converted from FirestormWoD garrison_plot_content.
-- Positions are RELATIVE to the building; our Plot::CreateGameObject relocates them via the SpawnMap.
-- creature guids 12000000+, gameobject guids 12000000+

DELETE FROM creature WHERE map IN (1212,1213,1214,1215,1216,1217,1218,1219,1221,1222,1223,1224,1225,1226,1227,1229,1230,1247,1248,1249,1252,1253,1254,1256,1257,1258,1259,1260,1278,1281,1282,1283,1284,1285,1286,1287,1288,1289,1290,1291,1292,1293,1296,1297,1298,1299,1300,1301,1302,1303,1308,1309,1333,1335,1336,1337,1339,1340,1344,1345,1346,1348,1349,1361,1362,1363,1364,1369,1370,1375,1376,1377,1378,1379,1380,1381,1382,1383,1384,1385,1386,1387,1388,1389,1390,1391,1392,1393,1396,1397,1398,1399,1400,1401,1405,1411,1412,1413,1414,1415,1416,1417,1418,1419,1420,1421,1422,1423,1424,1425,1426,1429,1430,1432,1433,1434,1435) AND guid >= 12000000;
DELETE FROM gameobject WHERE map IN (1212,1213,1214,1215,1216,1217,1218,1219,1221,1222,1223,1224,1225,1226,1227,1229,1230,1247,1248,1249,1252,1253,1254,1256,1257,1258,1259,1260,1278,1281,1282,1283,1284,1285,1286,1287,1288,1289,1290,1291,1292,1293,1296,1297,1298,1299,1300,1301,1302,1303,1308,1309,1333,1335,1336,1337,1339,1340,1344,1345,1346,1348,1349,1361,1362,1363,1364,1369,1370,1375,1376,1377,1378,1379,1380,1381,1382,1383,1384,1385,1386,1387,1388,1389,1390,1391,1392,1393,1396,1397,1398,1399,1400,1401,1405,1411,1412,1413,1414,1415,1416,1417,1418,1419,1420,1421,1422,1423,1424,1425,1426,1429,1430,1432,1433,1434,1435) AND guid >= 12000000;


